      fr: 'Guide complet pour votre transfert privé de La Mecque à Médine : comparatif avec le train rapide, choix du véhicule pour vos bagages, durée de route et paiement direct au chauffeur.',
      es: 'Guía completa para su traslado privado de La Meca a Medina: comparativa equilibrada con el tren, selección de vehículo familiar, duración del viaje y pago directo al chofer.',
      de: 'Ausführlicher Leitfaden für Ihren privaten Transfer von Mekka nach Medina: Zugvergleich, Fahrzeugauswahl für Großgepäck, Fahrzeit und Festpreise mit Barzahlung beim Fahrer.',
      hi: 'मक्का से मदीना प्राइवेट ट्रांसफर की संपूर्ण मार्गदर्शिका: ट्रेन से तुलना, परिवार और सामान के लिए गाड़ी का चुनाव, यात्रा का समय और केवल मदीना में ड्राइवर को भुगतान।',
      tr: 'Mekke’den Medine’ye özel transfer için kapsamlı rehber: trenle dengeli kıyaslama, aile ve bagaja göre araç seçimi, yolculuk süresi ve Medine’de şoföre ödeme kolaylığı.',
