          id: 'Ya, tentu saja. Anda dapat berhenti 20-30 menit di rest area modern untuk salat dan makan. Jika memesan arah sebaliknya dari Madinah ke Makkah untuk Umrah, kami sediakan pemberhentian gratis di Miqat Dzul Hulaifah (Bir Ali) untuk niat ihram.',
