          en: 'Match your group size and luggage volume to vehicle capacity: Toyota Camry sedan for 1-3 passengers (2 bags), Hyundai Staria VIP for up to 7 passengers (5-6 bags), GMC Yukon XL VIP for luxury and 6-8 large bags plus wheelchairs, and Toyota HiAce minibus for groups up to 11.',
          ms: 'Padankan saiz kumpulan dan jumlah beg dengan kapasiti kenderaan: sedan Toyota Camry untuk 1-3 penumpang (2 beg), Hyundai Staria VIP sehingga 7 penumpang (5-6 beg), GMC Yukon XL VIP untuk keselesaan 6-8 beg besar, dan van Toyota HiAce sehingga 11 penumpang.',
