          fr: 'Adaptez le véhicule à votre groupe : berline Camry pour 1 à 3 passagers (2 valises), Hyundai Staria VIP jusqu’à 7 passagers (5-6 valises), GMC Yukon XL VIP pour le prestige et 6 à 8 grandes valises, et minibus Toyota HiAce jusqu’à 11 personnes.',
