          en: 'Have ready: your exact route (hotel name or airport terminal), pickup date and precise time, total passenger count (adults and children), approximate number of large luggage bags, and your flight number for airport pickups to enable automatic arrival tracking.',
          ms: 'Sediakan: laluan tepat anda (nama hotel atau terminal lapangan terbang), tarikh dan masa pengambilan, bilangan penumpang (dewasa dan kanak-kanak), anggaran bilangan beg besar, dan nombor penerbangan untuk pemantauan ketibaan jika diambil dari lapangan terbang.',
          id: 'Siapkan: rute perjalanan pasti (nama hotel atau terminal bandara), tanggal dan jam penjemputan, jumlah penumpang (dewasa dan anak-anak), perkiraan jumlah koper besar, dan nomor penerbangan jika penjemputan dari bandara untuk pelacakan otomatis.',
          ur: 'اپنے پاس یہ معلومات تیار رکھیں: درست روٹ (ہوٹل کا نام یا ایئرپورٹ ٹرمینل)، پک اپ کی تاریخ اور وقت، مسافروں کی تعداد (بڑے اور بچے)، بڑے سامان کے بیگز کی تعداد، اور ایئرپورٹ پر استفسار کے لیے فلائٹ نمبر تاکہ آمد کا وقت ٹریک کیا جا سکے۔',
          fr: 'Préparez : l’itinéraire exact (nom de l’hôtel ou terminal d’aéroport), la date et l’heure précises de prise en charge, le nombre de passagers (adultes et enfants), le nombre approximatif de grandes valises, et votre numéro de vol pour le suivi en temps réel à l’aéroport.',
          es: 'Tenga a mano: la ruta exacta (nombre del hotel o terminal aérea), fecha y hora exacta de recogida, número de pasajeros (adultos y niños), cantidad aproximada de maletas grandes y el número de vuelo en caso de llegadas al aeropuerto.',
          de: 'Halten Sie bereit: die genaue Fahrtstrecke (Hotelname oder Flughafenterminal), Datum und präzise Abholzeit, Personenanzahl (Erwachsene und Kinder), ungefähre Anzahl großer Koffer sowie Ihre Flugnummer bei Flughafenabholungen zur Flugverfolgung.',
