          de: 'Sie können die Verfügbarkeit von Stundenpaketen (4- oder 8-Stunden-Blöcke) direkt in unserer Online-Buchungsmaske prüfen oder unserem WhatsApp-Team Ihre Wunschstadt (Mekka oder Dschidda), das Datum und die gewünschte Fahrzeugklasse mitteilen.',
